const K_COLORS=[['principal','Principal','#f0eaf5'],['roxo','Roxo','#f6f3ee'],['grafite','Grafite','#eeeae4'],['branco','Branco','#302737'],['negativo','Negativa','#56319a'],['laranja','Laranja','#211b29']];
function kDownloads(stem,sizes){return `<div class="k-downloads"><a download href="/assets/brand/${stem}.svg">SVG ↙</a>${sizes.map(w=>`<a download href="/assets/brand/${stem}-${w}.png">PNG ${w}px ↙</a>`).join('')}</div>`}
function kCards(kind){return K_COLORS.map(([key,label,bg])=>`<article class="k-card"><div class="k-preview ${kind}" style="background:${bg}"><img src="/assets/brand/catalisa-${kind}-${key}.svg" alt="${kind==='logo'?'catalisa':'c.'} — versão ${label}" loading="lazy"></div><div class="k-card-info"><h3>${label}</h3><span>Fundo transparente</span>${kDownloads('catalisa-'+kind+'-'+key,kind==='logo'?[256,512,1024,2048]:[64,128,256,512,1024])}</div></article>`).join('')}
function kPress(){return `<div class="k-page"><section class="k-hero"><div class="wrap"><span class="label">CATALISA / BRAND RESOURCES</span><div class="k-hero-grid"><div><h1>Uma marca.<br><em>Muitas expressões.</em></h1><p>A assinatura em minúsculas, o símbolo c. e as cores que conectam tudo. Recursos prontos para usar em produtos, apresentações e publicações.</p><a class="k-button" download href="/assets/brand/catalisa-press-kit.zip">Baixar kit completo · ZIP ↓</a><small>17 SVGs + 68 PNGs + guia rápido</small></div><div class="k-brand-art"><img src="/assets/brand/catalisa-simbolo-negativo.svg" alt="Símbolo c. em branco com ponto amarelo"><span>c. / A CONEXÃO COMEÇA AQUI</span></div></div></div></section><nav class="k-nav wrap" aria-label="Recursos de marca"><a href="#k-logo">Assinatura</a><a href="#k-symbol">Símbolo c.</a><a href="#k-applications">Aplicações</a><a href="#k-palette">Cores</a><a href="#k-guide">Como usar</a></nav><section class="wrap k-section" id="k-logo"><div class="k-heading"><span class="label">01 / ASSINATURA</span><h2>catalisa.<br>Em minúsculas. Por inteiro.</h2><p>A versão principal mantém o roxo e o ponto amarelo do site. Escolha uma alternativa monocromática ou negativa de acordo com o fundo e o contexto.</p></div><div class="k-grid">${kCards('logo')}</div></section><section class="k-symbol-section" id="k-symbol"><div class="wrap k-section"><div class="k-heading"><span class="label">02 / SÍMBOLO REDUZIDO</span><h2>Pequeno no espaço.<br>Presente na identidade.</h2><p>O c. concentra a assinatura para avatares, ícones e pontos de contato compactos. Prefira o nome completo quando a marca ainda não estiver identificada no contexto.</p></div><div class="k-grid">${kCards('simbolo')}</div></div></section><section class="wrap k-section" id="k-applications"><div class="k-heading"><span class="label">03 / PRONTO PARA APLICAR</span><h2>Do perfil<br>à próxima apresentação.</h2><p>Avatares quadrados e capas com fundo, em proporções próprias para cada uso. Os SVGs continuam editáveis em ferramentas vetoriais.</p></div><div class="k-avatars">${['roxo','claro','laranja'].map(c=>`<article><img src="/assets/brand/catalisa-avatar-${c}.svg" alt="Avatar Catalisa ${c}" loading="lazy"><h3>Avatar ${c}</h3>${kDownloads('catalisa-avatar-'+c,[128,256,512,1024])}</article>`).join('')}</div><div class="k-covers">${[['social','Social / 1200 × 630',1200],['apresentacao','Apresentação / 1920 × 1080',1920]].map(([s,l,w])=>`<article><img src="/assets/brand/catalisa-capa-${s}.svg" alt="Capa Catalisa para ${s}" loading="lazy"><h3>${l}</h3>${kDownloads('catalisa-capa-'+s,[w])}</article>`).join('')}</div></section><section class="k-palette-section" id="k-palette"><div class="wrap k-section"><div class="k-heading"><span class="label">04 / PALETA DO SITE</span><h2>Uma base roxa.<br>Acentos que conectam.</h2></div><div class="k-palette">${[['Roxo da assinatura','#56319A'],['Roxo de apoio','#734B9C'],['Amarelo do ponto','#FDC234'],['Laranja expressivo','#F18A43'],['Papel','#F6F3EE'],['Grafite','#1A1D23']].map(([n,h])=>`<button data-k-color="${h}" aria-label="Copiar ${n}, ${h}"><span style="background:${h}"></span><b>${n}</b><code>${h} ⧉</code></button>`).join('')}</div><p id="k-copy-status" role="status">Clique em uma cor para copiar o HEX.</p></div></section><section class="wrap k-section" id="k-guide"><div class="k-heading"><span class="label">05 / GUIA RÁPIDO</span><h2>Consistência<br>também é composição.</h2></div><div class="k-guide"><article><h3>Qual arquivo usar?</h3><p><strong>SVG</strong> para interfaces, impressão e escalas maiores. As letras estão convertidas em curvas: o arquivo não depende da instalação de uma fonte.</p><p><strong>PNG</strong> para apresentações, documentos e ferramentas que pedem imagem. O tamanho indicado é a largura total em pixels, incluindo a margem.</p></article><article><h3>Espaço e contraste</h3><p>Preserve a margem incluída nos arquivos e a proporção original. Escolha a versão branca ou negativa para fundos escuros e a principal para fundos claros.</p><p>Evite distorção, sombras adicionais, contornos ou a troca isolada das cores do ponto.</p></article><article><h3>Tipografia e linguagem</h3><p>Inter é a família usada no site. Títulos com espaço para respirar, textos diretos e formas geométricas ajudam a manter a mesma linguagem.</p><p>A assinatura e o símbolo deste pacote seguem a direção em minúsculas adotada aqui.</p></article></div><div class="k-final"><div><h3>Tudo em um arquivo.</h3><p>Logos, símbolos, avatares, capas e guia de uso.</p></div><a class="k-button" download href="/assets/brand/catalisa-press-kit.zip">Baixar press kit completo ↓</a></div></section></div>`}
const kPrev=cPage;cPage=function(route,blocks){return route==='/press-kit/'?kPress():kPrev(route,blocks)};
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-k-color]').forEach(b=>b.addEventListener('click',async()=>{const status=document.getElementById('k-copy-status');try{await navigator.clipboard.writeText(b.dataset.kColor);status.textContent=b.dataset.kColor+' copiado.'}catch{status.textContent='Copie este código: '+b.dataset.kColor}}))});
